package com.mediconnect.bootstrap;
import com.mediconnect.auth.domain.*; import com.mediconnect.auth.infrastructure.UserRepository; import org.slf4j.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.Profile; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional; import org.springframework.util.StringUtils;
@Component @Profile("dev") public class DevAdminInitializer implements CommandLineRunner { private static final Logger log=LoggerFactory.getLogger(DevAdminInitializer.class); private final UserRepository userRepository; private final PasswordEncoder passwordEncoder; private final String adminEmail; private final String adminPassword; public DevAdminInitializer(UserRepository userRepository,PasswordEncoder passwordEncoder,@Value("${app.bootstrap.admin-email:}") String adminEmail,@Value("${app.bootstrap.admin-password:}") String adminPassword){this.userRepository=userRepository;this.passwordEncoder=passwordEncoder;this.adminEmail=adminEmail;this.adminPassword=adminPassword;} @Override @Transactional public void run(String... args){if(!StringUtils.hasText(adminEmail)||!StringUtils.hasText(adminPassword)){log.info("DEV_ADMIN_EMAIL/DEV_ADMIN_PASSWORD were not provided; no development admin was bootstrapped.");return;}if(userRepository.existsByEmailIgnoreCase(adminEmail))return;userRepository.save(new UserEntity(adminEmail.trim().toLowerCase(),passwordEncoder.encode(adminPassword),Role.ROLE_ADMIN));log.info("Development admin account bootstrapped from environment variables: {}",adminEmail);} }
